macro_rules! impl_function_lookup {
    ($($field:ident => $variant:ident),+ $(,)?) => {
        impl Functions {
            pub fn lookup(&self, name: &str) -> Option<Function> {
                let key = name.to_uppercase();
                $(
                    if self.$field == key {
                        return Some(Function::$variant);
                    }
                )*
                None
            }
        }
    }
}

